(()=>{
'use strict';
const A=__ASSETS__,R=TownRules,E=FirstGuestPilot,S=FirstGuestStory,ui=document.getElementById('ui'),labels=document.getElementById('world-labels'),hazards=document.getElementById('mission-labels'),toastEl=document.getElementById('toast'),SAVE='first-guest.town.v2';
let s=R.initial(),stored=null,view='title',modal=null,paused=false,round=null,last=performance.now(),checkpoint=0,pitchPaint=-1,toastUntil=0,audioCtx=null,soundTick=0,roundLabels=new Map(),effects=new Map(),seasonFlash=0,announcement='',stageReply=null,speechLines=[],npcFocus=null,lastVoice=0;
try{const parsed=JSON.parse(localStorage.getItem(SAVE));if(R.valid(parsed))stored=parsed;}catch{}
let W;
try{W=new FirstGuestWorld(document.getElementById('world'),A,arrive);}catch(error){document.querySelector('.loading').innerHTML='<div><h2>입체 마을을 열 수 없어요</h2><p>Microsoft Edge 또는 Chrome에서 이 파일을 열어 주세요.<br>브라우저 설정에서 그래픽 가속이 켜져 있어야 해요.</p><p style="margin-top:18px">오류: '+escapeHTML(error.message)+'</p></div>';throw error;}
document.querySelector('.loading').hidden=true;
const points={need:{x:-13,z:5,name:'주민의 이야기'},stage:{x:9,z:-6,name:'발명 발표회'},contract:{x:-13,z:-5.2,name:'조달청 첫 구매'},field:{x:0,z:23,name:'시범사용 현장'},feedback:{x:-13,z:5,name:'현장 피드백'},growth:{x:15,z:12,name:'발명가의 공방'}};
const phaseIndex={need:0,stage:1,pitch:1,decision:2,contract:2,delivery:2,field:3,feedback:4,growth:4,report:4};
const objectives={need:['마을의 부탁을 들어요','공공기관이 겪는 문제부터 만나러 가요.','주민에게 걸어가기'],stage:['발명가 모두를 만나요','세 발명가의 움직이는 그림 발표를 들어요.','발표회로 걸어가기'],contract:['나라가 첫 손님이 될 차례','조달청에서 첫 구매 계약을 체결해요.','출장소로 걸어가기'],field:['약속한 성능을 확인해요','공공기관의 운용을 관찰하고 세 장의 사용 기록을 모아요.','시범사용 함께 보기'],feedback:['써본 사람의 의견을 들어요','성공과 아쉬움을 기록해서 기업에 전해요.','사용기관으로 걸어가기'],growth:['다음 발명이 자라고 있어요','첫 구매와 피드백이 무엇을 바꿨을까요?','공방으로 걸어가기']};
function escapeHTML(str){return String(str).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function image(key,cls='portrait',alt=''){return `<img class="${cls}" src="${A[key]}" alt="${alt}">`;}
function button(action,text,cls='primary',disabled=false){return `<button class="btn ${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`;}
function toast(text){toastEl.textContent=text;toastUntil=performance.now()+3500;}
function beep(kind='tap'){if(!s.sound)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';const n=kind==='good'?740:kind==='bad'?220:480;osc.frequency.setValueAtTime(n,audioCtx.currentTime);osc.frequency.exponentialRampToValueAtTime(n*(kind==='bad'?.7:1.3),audioCtx.currentTime+.12);gain.gain.setValueAtTime(.065,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+.22);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+.23);}catch{}}
function persist(){if(!s.started)return;s.position={x:W.player.group.position.x,z:W.player.group.position.z};s.round=round?JSON.parse(JSON.stringify(round)):null;try{localStorage.setItem(SAVE,JSON.stringify(s));stored=JSON.parse(JSON.stringify(s));}catch{if(!announcement){announcement='save';toast('브라우저 저장 공간이 부족해요. 창을 닫으면 진행이 사라질 수 있어요.');}}}
function season(){return R.seasons[s.season];}
function chapter(){return S.chapters[s.season];}
function promiseStrip(){return `<div class="promise-strip" aria-label="사계절 약속 기록">${S.chapters.map((c,i)=>{const h=s.history.find(h=>h.season===i);return `<span class="${h?.success?'kept':h?'working':i===s.season?'now':''}" title="${c.promise}">${R.seasons[i].icon} ${h?.success?'약속 한 걸음':h?'개선 중':i===s.season?'지금의 부탁':'아직 안 온 편지'}</span>`;}).join('')}</div>`;}
function products(){return R.lineup(s);}
function current(){return products()[s.selected??0];}
function maxLevel(){return Math.max(0,...Object.values(s.companies).map(c=>c.level));}
function hud(){return `<header class="hud"><div class="brand"><span class="season-orb" style="--season:${season().color}">${season().icon}</span><span><b>첫 손님</b><small>${season().name} · 혁신조달팀 나르미</small></span></div><div class="resources"><div class="resource"><small>시범구매 예산</small><b>${s.budget}<em>코인</em></b></div><div class="resource"><small>국민 안심</small><b>${s.safety}<em>/ 100</em></b></div><div class="resource"><small>혁신 성장</small><b>${s.growth}<em>새싹</em></b></div><button class="round-button" data-action="pause" aria-label="일시정지">Ⅱ</button></div></header>`;}
function title(){return `<section class="title-card paper"><div class="eyebrow">A LITTLE TRUST, A BIG TOMORROW</div><h1>첫 손님</h1><div class="subtitle">나라가 처음 사주는 날</div><p class="catch">“처음은, 나라가 믿어줄게요.”<br>작은 발명과 마을의 내일을 잇는<br>나르미의 사계절 이야기.</p>${stored?button('continue','이어서 출근하기','primary continue'):''}${button('new',stored?'새로운 일 년 시작':'마을로 출근하기',stored?'gold':'primary')}<button class="subtle" data-action="guide">어떻게 하는 게임인가요?</button></section><div class="title-notice"><small>달이의 오늘의 메모</small>팀장님! 마을에서 우리를 기다려요.</div><div class="title-footer">캐릭터 나르미·달이 © 조달청 · 등장 기업·기관·예산은 게임을 위한 가상 설정</div>`;}
function townUI(){const q=s.finished?['네 계절의 답장이 도착했어요','광장의 약속 등불과 모인 사용 기록을 둘러보세요.','연말 리포트 보기']:objectives[s.phase]||objectives.need;const goal=points[s.phase];return `${hud()}<aside class="quest paper"><div class="eyebrow">${season().icon} 모리와 할머니의 사계절 · ${s.season+1}장</div><h3>${chapter().title}</h3><p class="quest-purpose">${q[0]}</p><p>${q[1]}</p><div class="quest-steps" aria-label="${phaseIndex[s.phase]+1}단계 / 5단계">${S.steps.map((name,i)=>`<span title="${name}" class="${i<phaseIndex[s.phase]?'done':i===phaseIndex[s.phase]?'active':''}"></span>`).join('')}</div><small class="quest-stage">${S.steps[phaseIndex[s.phase]]} · 보상: ${chapter().reward}</small>${button(s.finished?'report':'navigate',q[2],'small primary')}${button('journal','편지와 약속 수첩','small')}</aside><div class="task-badge"><b id="nearby">${goal?'길을 눌러 걸어가세요':'마을을 둘러보세요'}</b><small>WASD / 방향키 이동 · E 대화 · Shift 달리기</small></div><div class="bottom-tools">${s.finished?'<button data-action="report">연말 리포트</button>':''}<button data-action="map">마을 지도</button><button data-action="collection">혁신 도감</button></div><div class="joystick" aria-label="이동 조이스틱"><span></span></div>`;}
function dialog(who,key,title,body,actions){return `<section class="dialog paper">${image(key,'portrait',who)}<span class="speaker">${who}</span><h3>${title}</h3><p data-speech="${escapeHTML(body)}" data-action="finishLine">${body}</p><div class="actions">${actions}</div></section>`;}
function sheet(title,content,options={}){return `<div class="sheet-backdrop"><section class="sheet paper ${options.wide?'wide':''}" role="dialog" aria-label="${title}"><div class="sheet-head"><div><div class="eyebrow">${options.eyebrow||'첫 손님 · 마을 이야기'}</div><h2>${title}</h2></div>${options.close?'<button class="close" data-action="close" aria-label="닫기">×</button>':''}</div>${content}</section></div>`;}
function needDialogue(){const prev=s.history.at(-1),bridge=s.season>0?(prev?.success?'지난 계절에 써본 기록이 다음 부탁으로 이어졌어요.':'지난번의 아쉬움도 기록했어요. 고칠 점을 안고 다음 부탁을 만나요.'):'주민의 편지가 공공기관의 요구가 되었어요.';return `<aside class="need-card paper"><div class="eyebrow">모리의 편지에서 시작된 부탁</div><h3>${season().institution}</h3><div class="request">${chapter().criterion}</div><p class="muted" style="margin-top:12px">${bridge}</p></aside>${dialog(season().person,'animal'+[2,3,6,5][s.season],season().need,season().detail+' 장비 운용과 현장 대응은 저희가 맡을게요. 팀장님은 필요한 기술을 골라 첫 구매와 사용 기록을 연결해 주세요.',button('acceptNeed','부탁을 맡고 발표회로 가기'))}`;}
function stageIntro(){return dialog('달이 · 현장 메모 담당','dari','오늘의 부탁을 해결할 기술을 찾을까요?',chapter().criterion+' — 이 약속을 기준으로 세 발표를 모두 들어요. 그다음 제품을 골라 직접 시연을 요청해요.',button('startPitch','세 발명가의 발표 듣기'));}
const pitchDuration=12,totalPitch=36;
function pitchInfo(){const i=Math.min(2,Math.floor(s.pitchTime/pitchDuration)),local=s.pitchTime-i*pitchDuration,step=local<1.8?0:local<5.2?1:local<10.3?2:3;return {i,step,local,p:products()[i]};}
function diagram(p,step){const n=s.season;return `<div class="diagram ${p.ability==='움직이는 눈'?'drone':''} ${p.old?'old':''}"><div class="hill"></div>${n===0?'<div class="tree"></div><div class="tree t2"></div><div class="cloud"></div>':n===3?'<div class="house"></div>':'<div class="rider"></div>'}${n===1?'<div class="rain"></div>':''}<div class="tech"></div>${step>0?'<div class="scan"></div>':''}<div class="signal">${step===0?'도움이 필요해요':step===1?p.fraud?'정확도 100%!?':p.old?'직접 확인!':'위험을 감지했어요':p.old?'검증된 사용 기록':p.back?'피드백 반영 완료':'첫 사용기관을 기다려요'}</div></div>`;}
function pitchUI(){const {i,step,local,p}=pitchInfo(),reply=stageReply&&stageReply.until>W.t&&stageReply.index===i?stageReply.text:null;const lines=['안녕하세요! 제 발명을 소개할게요.',p.quote,p.desc,p.old?'익숙한 기술도 꼼꼼히 비교해 주세요.':'첫 손님이 되어 주시면, 현장에서 더 좋아질 수 있어요.'];return hud()+`<section class="live-heading"><span class="tag">발명 발표회 · ${i+1} / 3</span><h2>${p.who}의 차례예요</h2><p>${['무대로 걸어 나오는 중','직접 소개할게요','작동하는 모습을 보세요','다음 발명가에게 박수!'][step]}</p><div class="live-progress"><span style="width:${s.pitchTime/totalPitch*100}%"></span></div></section><section class="live-speech paper"><div class="live-speech-copy"><span class="tag">${p.who}</span><p class="speech-text" data-speech="${escapeHTML(reply||lines[step])}" data-action="finishLine">${reply||lines[step]}</p><small>${p.name} · ${step===0?'잠깐만요, 곧 시작해요.':'말을 걸면 발명가가 반응해요.'}</small></div><div class="live-reactions">${button('applaud','짝짝! 응원하기','small gold')}${button('askWeakness','약점도 있나요?','small',step===0)}${button('repeatDemo','시연 한 번 더','small',local<8.2||step===3)}</div></section>`;}
function decisionUI(){return hud()+`<section class="decision-heading"><span class="tag">3명 모두 만났어요</span><h2>어떤 발명에 첫 기회를 줄까요?</h2><p>오늘의 기준: ${chapter().criterion}</p></section><section class="decision-tray paper"><div class="product-grid">${products().map((p,i)=>`<button class="product ${s.selected===i?'selected':''}" data-select="${i}" aria-pressed="${s.selected===i}" ${p.fraud&&s.caught?'disabled':''}><span class="tag ${p.old?'gold':p.back?'pink':''}">${p.fraud&&s.caught?'시연 불일치 · 제외':p.old?'검증된 기존 제품':p.back?'피드백으로 레벨업':'첫 손님을 기다려요'}</span>${s.selected===i?'<span class="checked">✓</span>':''}<h3>${p.name}</h3><p>${p.ability}${p.back?' · 가격 20% ↓':''}<br>${s.inspected.includes(p.id)?'확인한 성능 '+'★'.repeat(p.stars):p.old?'현장 사용 기록 128곳':'시연에서 성능을 확인해요'}</p><span class="company">${p.company}</span><div class="price">${p.price}<small> 코인</small></div></button>`).join('')}</div><div class="research"><span>발표보다 실제 기술!</span>${button('demo','직접 시연 요청','small',s.selected===null)}${button('ai','AI 분석','small',s.selected===null)}${button('evidence','근거 보기','small',s.selected===null)}</div><footer class="decision-footer"><div class="scale"><button data-scale="small" class="${s.scale==='small'?'active':''}">조금 사보기<small>한 곳에서 차근차근</small></button><button data-scale="large" class="${s.scale==='large'?'active':''}">넓게 써보기<small>비용 ×2 · 성장 +2</small></button></div>${button('toContract',s.selected===null?'제품을 골라주세요':`첫 구매 연결 · ${current().price*(s.scale==='large'?2:1)} 코인`,'primary',s.selected===null||!R.canBuy(s,s.selected))}</footer><p class="budget-note">${s.selected!==null&&!s.inspected.includes(current().id)?'구매 전에 직접 시연을 요청해, 발표와 실제 작동을 대조해 주세요.':s.selected!==null&&!R.canBuy(s,s.selected)?'다음 계절 예산도 남겨야 해요. 구매 범위를 줄이거나 다른 제품을 골라보세요.':'조달청이 먼저 사고, 공공기관이 실제로 써본 뒤 함께 개선해요.'}</p></section>`;}
function contractUI(){const p=current(),cost=p.price*(s.scale==='large'?2:1);return sheet(p.old?'필요한 장비를 현장으로': '첫 사용 기록이 생기는 순간',`<p>${season().institution}의 <b>“${season().request}”</b>에 맞춰 <b>${p.name}</b>을 ${s.scale==='large'?'넓은 범위':'작은 범위'}에서 사용해요.</p><div class="policy-path"><div class="policy-node">${image('animal'+p.sprite)}<small>${p.old?'공급기업':'혁신기업'}</small><b>${p.company}</b><p>기술을 만들고 납품</p></div><div class="policy-node highlight">${image('narmi')}<small>조달청</small><b>${p.old?'공공구매':'시범구매'}</b><p>예산으로 먼저 구매</p></div><div class="policy-node">${image('animal'+[2,3,6,5][s.season])}<small>공공기관</small><b>${season().institution}</b><p>실제 사용 · 결과 전달</p></div></div><div class="contract-price"><span>이번 구매 금액</span><br><b>${cost}</b> 코인<small>남는 예산 ${s.budget-cost} 코인 · 게임 속 가상 예산입니다</small></div><div class="actions">${button('backDecision','제품 다시 비교','')}${button('purchase','구매 도장 찍기','primary',!R.canBuy(s,s.selected))}</div>`,{eyebrow:'조달청 · 첫 손님 계약서'});}
function deliveryUI(){return `${hud()}<section class="delivery-banner paper"><span class="tag">${s.product.old?'공공구매':'조달청 시범구매'} 완료</span><h2>첫 주문이, 현장으로 가고 있어요.</h2><p>${s.product.company}의 제품을 ${season().institution}에 보내요.<br>모리의 부탁이, 첫 주문서가 되었어요. 도착하면 함께 사용 기록을 모아요.</p><div class="progress-line"><span id="delivery-progress"></span></div></section>`;}
function fieldIntro(){return sheet('이제, 써본 기록을 만들어요.',`<div class="mission-intro">${image('animal'+[2,3,6,5][s.season])}<p><b>${chapter().operator}</b>가 장비를 운용하고 현장에 대응해요.</p><div class="research-note"><b>팀장님의 할 일은 관찰과 기록!</b><p>세 가지 시험 조건을 차례로 시작해요.<br>제품이 알렸는지, 담당자가 어떻게 대응했는지 보고<br>실제로 본 결과를 사용 기록에 남겨주세요.</p></div><div class="request">확인할 약속 · ${chapter().criterion}</div><div class="role">${s.product.name}을 안전하게 구성한 모의 현장에서 시험해요.<br>시험 시간·성능 수치는 게임 설정입니다. 실제 재난을 직접 처리하는 체험은 아니에요.</div><div class="actions" style="justify-content:center">${button('beginField','사용 기록 수첩 펼치기')}</div></div>`,{eyebrow:season().institution+' · 시범사용 입회'});}
function fieldUI(){const c=E.current(round),done=round.phase==='recorded',record=round.phase==='record',running=round.phase==='running';const choices=E.answers.filter(x=>x.id===c.answer||x.id===(c.answer==='quiet'?'timely':'quiet')||x.id===(c.answer==='backup'?'false':'backup'));return `${hud()}<section class="pilot-heading"><span class="tag">사용 기록 ${round.caseIndex+1} / 3 · ${season().institution}</span><h2>${c.title}</h2><p>운용·대응: ${chapter().operator} &nbsp;|&nbsp; 관찰·기록: 나르미</p></section><section class="pilot-panel paper" aria-label="시범사용 관찰 수첩"><div class="pilot-progress">${round.cases.map((test,i)=>`<span class="${i<round.records.length?'done':i===round.caseIndex?'active':''}">${i<round.records.length?'✓':i+1} ${['기본 조건','일상과 구별','어려운 조건'][i]}</span>`).join('')}</div>${running?`<span class="tag">담당 기관이 운용 중</span><p id="pilot-live" aria-live="polite">시험 조건을 만들고 있어요…</p><div class="progress-line"><span id="pilot-progress"></span></div><small>서두르지 않아도 돼요. 끝까지 보고 기록해요.</small>`:record?`<span class="tag">관찰 완료 · 기록에 도장을 찍어요</span><p class="pilot-log">${c.log}</p><div class="observation-options">${choices.map(x=>`<button data-observation="${x.id}">${x.text}</button>`).join('')}</div><div id="record-hint" role="status"></div>${button('pilotReplay','장면 다시 보기','small')}`:done?`<div class="record-stamp">✓ 사용 기록 ${round.caseIndex+1}장</div><h3>${c.result}</h3><p>${c.needMet?'오늘의 약속을 지킨 조건이에요.':'아쉬운 점도 빠짐없이 적었어요. 이 기록이 개선의 출발점이에요.'}</p>${button('pilotNext',round.caseIndex===2?'세 장의 기록을 모아보기':'다음 조건 시험하기')}`:`<span class="tag">다음 시험 조건</span><h3>${c.condition}</h3><p>알림이 필요한 순간과 담당자의 대응을 함께 살펴요.</p>${button('pilotStart',round.caseIndex===0?'기관에 첫 시험 시작 요청':'이 조건으로 시험 요청')}`}<small class="pilot-caption">안전하게 구성한 모의 시범사용 · 세 조건을 모두 관찰해요</small></section>`;}
function resultUI(){const r=s.result;return sheet(r.success?'부탁에 한 걸음 가까워졌어요.':'다음 시험을 위한 숙제가 생겼어요.',`<div class="result-stars">${'★'.repeat(r.stars)}${'☆'.repeat(3-r.stars)}</div><p><b>${chapter().criterion}</b><br>${season().institution}의 운용 결과를 기록했어요.</p><div class="score-grid"><div><b>${r.hits}/${r.total}</b><small>요구에 맞았던 조건</small></div><div><b>${r.safetyDelta>=0?'+':''}${r.safetyDelta}</b><small>국민 안심</small></div><div><b>+${r.growth}</b><small>혁신 성장</small></div></div><div class="resident-letter">${r.success?chapter().good:chapter().bad}</div><div class="report-copy">${s.product.old?'기존 장비의 사용 기록을 확인했어요. 익숙한 기술도 현장의 요구에 맞는지 살펴야 해요. 새로운 기업의 첫 사용 기록은 생기지 않았어요.':r.success?'“써본 곳이 없어요”가 “이 조건에서는 이렇게 작동했어요”로 바뀌었어요. 잘된 점과 한계를 함께 남긴 기록이 다음 고객의 판단 근거가 됩니다.':'기회를 주는 것과 성능을 보장하는 것은 달라요. 사용기관의 추가 대응이 필요했던 조건을 기업에 정확히 알려주세요.'}</div><div class="actions">${button('toFeedback','이 기록을 들고 사용기관 만나기')}</div>`,{eyebrow:'조달청 · 약속과 실제 결과 대조'});}
function feedbackUI(){const r=s.result,note=r.records?.find(c=>c.issue)?.log||(r.kind==='pilot'?'세 시험 조건을 통과했어요. 다음에는 다른 장소에서도 같은 성능이 나오는지 확인하고 싶어요.':'이전 사용 기록에서 확인한 개선점: '+(E.issues[r.weakness]||'현장 요구를 다시 확인해 주세요.')),keys=[r.weakness,...Object.keys(E.issues).filter(k=>k!==r.weakness).slice(0,2)].sort();return sheet('어떤 점을 고치면, 다음이 달라질까요?',`<div class="row">${image('animal'+[2,3,6,5][s.season])}<div><span class="tag">${season().institution} · 함께 적은 기록</span><p style="margin-top:10px">${note}</p></div></div><p style="margin-top:16px"><b>${s.product.company}에 전달할 의견을 골라요.</b></p><div class="feedback-options">${keys.map(key=>`<button data-feedback="${key}">${E.issues[key]}</button>`).join('')}</div><div id="feedback-hint" role="status"></div><p class="muted" style="margin-top:15px">실제 사용 기록에 맞는 의견이 제품 개선으로 이어져요.</p>`,{eyebrow:'사용기관의 의견 · 기업에 전하는 개선 요청'});}
function growthUI(){const p=s.product,c=s.companies[p.id],h=s.history.at(-1),level=c?.level||0;return `${hud()}<section class="growth-card paper"><div class="eyebrow">주민에게 답장하고 · 발명가에게 다음 기회를</div>${image('animal'+p.sprite)}<h2>${p.old?'현장을 지켰어요':p.fraud?'기술부터 다시 확인해요':level>0?'우리 공방이 자라고 있어요!':'다시 도전할 준비가 됐어요'}</h2><p>${p.old?'검증된 장비가 마을에 남았어요. 다음 계절에는 새로운 기술의 첫 손님도 만나볼까요?':p.fraud?'발표와 실제 기술이 달랐어요. 제품 평가에서는 작동 원리와 성능 확인이 먼저예요.':h.feedbackCorrect?'사용기관의 의견을 반영해 성능을 개선했어요. 다음에는 20% 저렴한 개선판으로 돌아올게요! 이번에 지적한 조건도 다시 시험해 주세요.':'전해주신 의견을 기록했어요. 실제로 겪은 문제에 더 맞는 피드백이었다면 성능도 높일 수 있었을 거예요.'}</p><div class="resident-letter">${chapter().next}</div><div class="growth-track">${['차고','공방','공장','해외'].map((x,i)=>`<span class="${!p.old&&!p.fraud&&i<=level?'active':''}">${x}</span>`).join('')}</div><p class="muted">${!p.old&&!p.fraud?'조달청의 첫 구매 → 실제 사용 기록 → 기술 개선과 다음 고객':'조달청은 공공기관에 필요한 제품을 연결해요.'}</p>${button('nextSeason',s.season===3?'일 년의 이야기 돌아보기':'다음 계절을 맞이하기')}</section>`;}
function reportUI(){const appointed=s.safety>=75&&s.growth>=4,safeOnly=s.history.every(h=>h.product.old);const copy=safeOnly?'안전한 선택만 했어요. 현장을 지켰지만, 새로운 기술의 첫 사용 기록은 만들지 못했어요.':appointed?'주민의 안심과 새로운 기술의 성장을 함께 만들었어요. 처음 써본 기록이 마을의 다음 계절을 바꿨습니다.':s.safety<75?'새 기술에 기회를 주었지만, 현장의 안심을 더 챙길 필요가 있어요. 다음에는 시연과 사용 기록을 꼼꼼히 확인해 보세요.':'마을의 안심은 지켰어요. 다음 해에는 처음 도전하는 기업에게도 더 많은 기회를 줄 수 있을까요?';return `${hud()}${sheet(appointed?'“내년에도 맡아주세요!”':'일 년의 첫 손님 리포트',`<div class="score-grid"><div><b>${s.safety}</b><small>국민 안심 · 목표 75</small></div><div><b>${s.growth}</b><small>혁신 성장 · 목표 4</small></div><div><b>${s.history.filter(h=>!h.product.old&&!h.product.fraud).length}</b><small>새 기술의 첫 사용</small></div></div>${promiseStrip()}<div class="resident-letter">“우리의 부탁이 주문서가 되고, 써본 기록이 다음 발명을 바꿨어요.” — 모리와 도담 할머니</div><div class="report-copy">${copy}<br><b>조달청은 필요한 공공기관과 새 기술을 연결하고, 첫 구매와 실제 사용 기록으로 더 나은 공공서비스를 돕습니다.</b></div>${s.history.map(h=>`<div class="report-row"><span class="season-orb" style="--season:${R.seasons[h.season].color}">${R.seasons[h.season].icon}</span><div><b>${h.product.name}</b><small>${h.kind==='pilot'?h.hits+'/'+h.total+' 조건 충족':h.hits+'/'+h.total+' 이전 사용 기록'} · ${S.chapters[h.season].promise} · ${h.feedbackCorrect?'현장 의견을 반영한 개선':'사용 결과 기록'}</small></div><strong>${h.product.old?'기존 제품':h.success?'첫 사용 성공':'다시 도전'}</strong></div>`).join('')}<div class="actions">${button('facts','현실의 혁신조달 이야기','')}${button('share','나의 혁신 도감 저장','gold')}${button('explore','달라진 마을 둘러보기','primary')}</div>`,{wide:true,eyebrow:'국민의 안심과 기업의 성장 · 조달청의 일 년'})}`;}
function render(){W.keys={};W.stick={x:0,y:0};labels.innerHTML='';const titleMode=view==='title';document.body.dataset.phase=titleMode?'title':s.phase;document.body.dataset.modal=modal||'';W.setGoal(!titleMode&&W.mode==='town'&&!modal?points[s.phase]:null);let html=titleMode?title():s.phase==='pitch'?pitchUI():s.phase==='decision'?decisionUI():s.phase==='delivery'?deliveryUI():round?fieldUI():s.phase==='report'&&view!=='explore'?reportUI():view==='growth'?growthUI():townUI();if(modal==='prologue')html+=prologueUI();if(modal==='journal')html+=journalUI();if(modal==='chapterLetter')html+=chapterLetterUI();if(modal==='need')html+=needDialogue();if(modal==='stage')html+=stageIntro();if(modal==='contract')html+=contractUI();if(modal==='fieldIntro')html+=fieldIntro();if(modal==='result')html+=resultUI();if(modal==='feedback')html+=feedbackUI();if(modal==='demo')html+=demoModal();if(modal==='ai')html+=aiModal();if(modal==='evidence')html+=evidenceModal();if(modal==='map')html+=mapModal();if(modal==='collection')html+=collectionModal();if(modal==='facts')html+=factsModal();if(modal==='guide')html+=guideModal();if(modal==='npcChat')html+=npcChat();if(modal==='newConfirm')html+=confirmModal();if(paused)html+=pauseModal();if(seasonFlash>0)html+=`<div class="new-season"><div><b>${season().icon} ${season().name}</b><p>${season().title}</p></div></div>`;ui.innerHTML=html;bindJoystick();startSpeech();if(!titleMode&&W.mode==='town'&&!modal&&!paused&&points[s.phase]){const h=document.createElement('button');h.className='world-hotspot';h.dataset.action='navigate';h.textContent=points[s.phase].name;h.setAttribute('aria-label',points[s.phase].name+'으로 이동');labels.appendChild(h);}if(s.phase==='pitch'){const p=pitchInfo();pitchPaint=p.i*4+p.step;}}
function layer(content){return `<div class="modal-layer"><section class="sheet paper" role="dialog"><div class="row between" style="margin-bottom:16px"><span class="eyebrow">달이의 현장 가방</span><button class="close" data-action="close" aria-label="닫기">×</button></div>${content}</section></div>`;}
function demoModal(){const p=current();return `<div class="modal-layer live-demo"><section class="live-heading"><span class="tag">직접 시연 · 기술 중심 평가</span><h2>${p.fraud?'잠깐, 커튼 뒤를 볼까요?':'발명가가 직접 보여드릴게요.'}</h2></section><section class="live-speech paper" role="dialog"><div class="live-speech-copy"><span class="tag">${p.who}</span><h3>${p.fraud?'“잠깐! 커튼은 열지 마세요!”':p.name}</h3><p data-speech="${escapeHTML(p.fraud?'뒤에서 사람이 버튼을 누르고 있었어요. AI 기술이라는 발표와 실제 작동이 달라, 구매 후보에서 제외했어요.':p.desc+' '+p.limit)}" data-action="finishLine">${p.fraud?'뒤에서 사람이 버튼을 누르고 있었어요.':p.desc+' '+p.limit}</p><small>${p.fraud?'화려한 말보다 실제 기술을 확인했어요.':'확인한 성능 '+'★'.repeat(p.stars)+' · 장점과 약점을 함께 확인해요.'}</small></div><div class="live-reactions">${button('demoReplay','다시 작동시켜 보기','small gold')}${button('close','비교표로 돌아가기','small primary')}</div></section></div>`;}
function aiModal(){const p=current(),wrong=s.aiErrorSlot===s.season;const claim=wrong?'약점 없이 어떤 상황에서도 완벽하게 작동합니다. 추가 확인은 필요 없어 보입니다.':p.fraud?'화려한 설명에 비해 실제 작동 근거가 부족합니다. 직접 시연을 확인해야 합니다.':p.desc+' 다만 '+p.limit;return layer(`<div class="row">${image('dari')}<div><span class="tag">AI 분석 · 확인 전 주장</span><h2 style="margin-top:8px">달이가 분석 결과를 가져왔어요</h2></div></div><div class="research-note"><p>“${claim}”</p></div><p>AI의 말도 틀릴 수 있어요. 제품의 실제 시연 기록과 대조해 보세요.</p><div class="actions">${button('evidence','근거와 대조하기')}${button('close','닫기','')}</div>`);}
function evidenceModal(){const p=current(),wrong=s.aiErrorSlot===s.season&&s.analysis;return layer(`<h2>근거는, 실제 작동과 사용 기록</h2><div class="research-note ${wrong?'error':''}"><b>${wrong?'AI의 자신만만한 설명을 바로잡았어요':'확인된 자료를 읽어봐요'}</b><p>${wrong?'모든 상황에서 완벽하다는 주장은 근거가 없어요. ':''}${p.fraud?'AI 자동 분석이라는 발표를 입증할 기술 자료가 없어요. 시연을 요청하면 작동 원리를 확인할 수 있어요.':p.desc+' '+p.limit}</p></div><div class="evidence"><b>제품 시험 기록</b><br>${p.old?'기존 사용처 128곳 · 정해진 구역에서 검증된 장비':p.back?'지난 계절 시범사용 기록 있음 · 개선판 제출':'공공기관 사용 실적 없음 · 첫 현장 검증이 필요함'}<br>이번 현장의 요구: ${season().request}</div><p class="muted" style="margin-top:16px">게임 속 제품 시험 자료입니다. 달이는 자료를 전달하고, 판단은 팀장님이 해요.</p><div class="actions">${button('close','확인했어요')}</div>`);}
function mapModal(){return layer(`<h2>한 걸음씩, 마을의 내일로</h2><p class="muted">장소를 누르면 나르미가 길을 찾아 걸어가요.</p><div class="map-grid"><button class="map-place" style="left:24%;top:17%" data-place="contract">조달청 출장소</button><button class="map-place" style="left:75%;top:17%" data-place="stage">발명 발표회</button><button class="map-place" style="left:23%;top:49%" data-place="need">${season().institution}</button><button class="map-place" style="left:77%;top:49%" data-place="growth">발명가 공방</button><button class="map-place" style="left:50%;top:83%" data-place="field">시범사용 현장</button></div>`);}
function collectionModal(){const cs=Object.values(s.companies).filter(c=>!c.name.includes('무엇이든'));return layer(`<h2>나의 혁신 도감</h2><p class="muted" style="margin:10px 0 18px">첫 구매가 만든 실제 기록이 이곳에 모여요.</p>${cs.length?`<div class="collection">${cs.map(c=>`<article>${image('animal'+c.sprite)}<h3>${c.name}</h3><p>${['차고 · 첫 도전','공방 · 첫 주문','공장 · 다음 고객','해외 · 세계로'][c.level]}</p></article>`).join('')}</div>`:'<div class="report-copy">아직 첫 손님이 되어준 기업이 없어요. 주민의 부탁을 듣고 첫 구매를 시작해 보세요.</div>'}<div class="actions">${s.history.length?button('share','도감 이미지 저장','gold'):''}${button('close','마을로 돌아가기')}</div>`);}
function factsModal(){return layer(`<h2>게임 밖에도, 첫 손님이 있어요.</h2><div class="report-copy">혁신제품 시범구매는 조달청 예산으로 혁신제품을 구매해 공공기관에 제공하고, 실제 사용 결과를 평가·피드백하는 사업이에요. 이 게임의 구매, 현장 사용, 개선 흐름을 여기서 가져왔어요.</div><div class="policy-path"><div class="policy-node"><small>2026 시범구매 예산</small><b>839억 원</b></div><div class="policy-node"><small>AI 제품의 기회</small><b>AI 전용 트랙</b></div><div class="policy-node"><small>2030년 목표</small><b>혁신제품 5,000개</b></div></div><p class="muted">숫자는 해당 발표의 예산·목표이며, 달성 실적을 뜻하지 않아요. 게임은 정책의 핵심 흐름을 단순화한 가상 체험입니다.</p><div class="sources"><a href="https://www.pps.go.kr/kor/content.do?key=00648" target="_blank" rel="noopener">조달청 · 혁신제품 지정과 시범구매 절차</a><br><a href="https://www.pps.go.kr/kor/bbs/view.do?bbsSn=2512180012&key=00318" target="_blank" rel="noopener">2026년 혁신제품 시범구매 예산</a><br><a href="https://www.pps.go.kr/kor/bbs/view.do?bbsSn=2602040011&key=00634" target="_blank" rel="noopener">AI 전용 트랙</a><br><a href="https://www.pps.go.kr/kor/bbs/view.do?bbsSn=2509110007&key=00318" target="_blank" rel="noopener">2030년 혁신조달 확대 목표</a></div><div class="actions">${button('close','이야기로 돌아가기')}</div>`);}
function guideModal(){return layer(`<h2>나라의 첫 구매로 마을을 바꿔요.</h2><div class="policy-path"><div class="policy-node"><small>먼저 듣고</small><b>주민의 부탁</b><p>공공기관의 필요 찾기</p></div><div class="policy-node"><small>꼼꼼히 보고</small><b>기술의 시연</b><p>모든 발표 후 비교</p></div><div class="policy-node"><small>직접 써보고</small><b>첫 구매와 개선</b><p>사용 기록과 피드백</p></div></div><p><b>길을 클릭하거나 WASD·방향키로 걸어요.</b><br>목적지 안내 버튼을 누르면 길을 찾아가요. 가까이에서 E키로 대화할 수 있어요. 휴대폰은 왼쪽 조이스틱으로 이동해요.</p><div class="report-copy">주민의 편지에서 시작해, 실제로 본 사용 기록으로 답장해요.<br>운용과 현장 대응은 공공기관이 맡고, 나르미는 관찰·기록·개선 의견을 맡아요.<br>한 해의 목표: <b>국민 안심 75 이상 + 혁신 성장 4 이상</b><br>AI 분석은 한 해에 한 번, 자신만만하게 틀려요. 근거를 꼭 확인해 보세요.</div><div class="actions">${button('close','준비됐어요')}</div>`);}
function confirmModal(){return layer(`<h2>새로운 일 년을 시작할까요?</h2><p style="margin:16px 0">현재 저장된 진행을 새 이야기로 바꿉니다. 도감 이미지는 먼저 저장할 수 있어요.</p><div class="actions">${button('close','돌아가기','')}${button('reset','새로 시작하기','gold')}</div>`);}
function pauseModal(){return `<div class="modal-layer"><section class="paper pause" role="dialog" aria-label="일시정지"><span class="eyebrow">잠깐, 차 한 잔</span><h2 style="margin-top:8px">마을도 잠시 쉬어요.</h2><p>발표와 현장 시간은 멈춰 있어요.<br>지금까지의 진행은 자동으로 저장했어요.</p>${button('resume','다시 출근하기')}${button('sound',s.sound?'효과음 끄기':'효과음 켜기','')}${button('toTitle','첫 화면으로','')}</section></div>`;}
function setupWorld(){W.currentRound=null;W.setSeason(s.season);W.setLineup(products());W.buildLab(maxLevel());W.player.group.position.set(s.position?.x??-6,.04,s.position?.z??2);W.dari.group.position.copy(W.player.group.position).add(new THREE.Vector3(-1,0,1));s.history.forEach(h=>W.install(h.product,h.season));W.delivery.visible=s.phase==='delivery';W.van.visible=false;W.drone.visible=false;}
function startNew(){s=R.initial();s.started=true;stored=null;round=null;view='town';modal='prologue';paused=false;W.installed?.forEach(({g})=>W.scene.remove(g));W.installed=[];W.currentRound=null;setupWorld();W.setMode('town');hazards.innerHTML='';roundLabels.clear();effects.clear();checkpoint=0;render();persist();}
function resumeSaved(){s=JSON.parse(JSON.stringify(stored));if(!s.storyVersion){try{localStorage.setItem('first-guest.town.before-story',JSON.stringify(s));}catch{}s.storyVersion=1;s.prologueDone=true;if(s.round){s.round=null;s.phase='field';}toast('이전 예산과 구매는 이어받았어요. 현장 체험은 새 사용 기록 방식으로 시작해요.');}round=E.validRound(s.round)?s.round:null;view='town';modal=s.prologueDone?null:'prologue';paused=false;setupWorld();if(s.phase==='pitch'||s.phase==='decision')W.setMode('pitch');else if(s.phase==='delivery')W.setMode('delivery');else if(round){W.currentRound=round;W.setMode('field');paused=true;}else if(s.phase==='report'){view='report';W.setMode('report');}else W.setMode('town');render();persist();}
function arrive(type){if(!type)return;if(type.startsWith('greet:')){npcFocus=W.actors[Number(type.split(':')[1])];W.chatActor=npcFocus;modal='npcChat';W.react(npcFocus,'wave',2);W.react(W.player,'wave',1.7);render();return;}if(type===s.phase){if(type==='need'||type==='stage'||type==='contract'||type==='feedback')modal=type;else if(type==='field'){W.setMode('field');modal='fieldIntro';}else if(type==='growth'){view='growth';W.setMode('growth');W.buildLab(maxLevel());W.growthAt=W.t;W.burst(16,4,8,'#f5dc89',32);W.react(W.player,'cheer',3);beep('good');}render();persist();}else toast('오늘의 부탁은 왼쪽 메모에서 확인해요.');}
function navigate(type=s.phase){const p=points[type];if(!p)return;modal=null;W.setMode('town');W.navigate(p.x,p.z,type);render();}
function closeModal(){const old=modal;modal=null;if(old==='fieldIntro'){W.setMode('town');}render();}
function handle(action){if(paused&&!['resume','sound','toTitle'].includes(action))return;beep();switch(action){
 case 'new':if(stored){modal='newConfirm';render();}else startNew();break;
 case 'reset':startNew();break;
 case 'continue':resumeSaved();break;
 case 'greetBack':W.react(npcFocus,'cheer',2.5);W.react(W.player,'wave',2.5);toast('마을 친구가 반갑게 손을 흔들어요.');break;
 case 'guide':modal='guide';render();break;
 case 'journal':modal='journal';render();break;
 case 'prologueNext':if((s.prologueStep||0)<2){s.prologueStep=(s.prologueStep||0)+1;render();persist();}else{s.prologueDone=true;modal=null;navigate('need');persist();}break;
 case 'readLetter':modal=null;navigate('need');persist();break;
 case 'pilotStart':case 'pilotReplay':if(round&&E.start(round)){render();persist();}break;
 case 'pilotNext':if(round&&E.next(round)){if(round.done)finishRound();else{render();persist();}}break;
 case 'close':closeModal();break;
 case 'finishLine':finishSpeech();break;
 case 'applaud':{const {i,p}=pitchInfo();W.stageReaction('clap',i);stageReply={index:i,until:W.t+2.8,text:p.fraud?'훗, 역시 제 발표는 완벽하죠?':'고마워요! 더 열심히 보여드릴게요!'};render();break;}
 case 'askWeakness':{const {i,p}=pitchInfo();W.stageReaction('question',i);stageReply={index:i,until:W.t+3.5,text:p.fraud?'약점이요? 그, 그건… 커튼은 열지 마세요!':p.limit+' 그래서 현장의 의견이 필요해요.'};render();break;}
 case 'repeatDemo':{const {i}=pitchInfo();s.pitchTime=i*12+5.2;stageReply={index:i,until:W.t+2,text:'좋아요! 여기, 움직이는 모습을 다시 봐주세요.'};W.react(W.presenters[i],'point',2);render();break;}
 case 'demoReplay':W.demoStart=W.t;W.react(W.presenters[s.selected??0],'point',2);beep();break;
 case 'navigate':navigate();break;
 case 'interact':{const p=points[s.phase];if(p&&Math.hypot(p.x-W.player.group.position.x,p.z-W.player.group.position.z)<3.1)arrive(s.phase);else navigate();break;}
 case 'acceptNeed':s.phase='stage';navigate('stage');persist();toast('부탁을 수첩에 담았어요. 달이와 발표회로 함께 가요.');break;
 case 'startPitch':toastEl.textContent='';stageReply=null;s.phase='pitch';s.pitchTime=0;s.watched=0;modal=null;W.setMode('pitch');render();persist();break;
 case 'demo':{if(s.selected===null)break;const p=current();if(!s.inspected.includes(p.id))s.inspected.push(p.id);if(p.fraud){s.caught=true;beep('bad');}modal='demo';W.demoStart=W.t;W.stageEvent=null;render();persist();break;}
 case 'ai':if(s.selected===null)break;s.analysis=true;modal='ai';render();persist();break;
 case 'evidence':if(s.selected===null)break;if(s.analysis&&s.aiErrorSlot===s.season&&!s.corrected){s.corrections++;s.corrected=true;}s.evidence=true;modal='evidence';render();persist();break;
 case 'toContract':if(s.selected===null||!R.canBuy(s,s.selected))break;s.phase='contract';navigate('contract');persist();toast('이 기술을 고른 이유를 계약서에 담아요. 출장소로 함께 가요.');break;
 case 'backDecision':s.phase='decision';modal=null;W.setMode('pitch');render();persist();break;
 case 'purchase':if(!R.purchase(s))break;modal=null;W.setMode('delivery');W.delivery.visible=true;W.delivery.position.set(-22,.3,1);render();persist();beep('good');break;
 case 'beginField':toastEl.textContent='';if(round||s.history.some(h=>h.season===s.season))break;round=E.create({season:s.season,product:s.product,scale:s.scale,seed:s.seed+s.season*911});modal=null;W.currentRound=round;checkpoint=0;W.setMode('field');hazards.innerHTML='';roundLabels.clear();effects.clear();render();persist();break;
 case 'toFeedback':W.currentRound=null;navigate('feedback');persist();break;
 case 'nextSeason':{R.next(s);s.corrected=false;view=s.finished?'report':'town';modal=null;W.setSeason(s.season);W.setLineup(products());W.setMode(s.finished?'report':'town');if(!s.finished){seasonFlash=2.4;modal='chapterLetter';}render();persist();break;}
 case 'pause':if(view==='title')break;paused=true;persist();render();break;
 case 'resume':paused=false;last=performance.now();render();break;
 case 'sound':s.sound=!s.sound;render();persist();break;
 case 'toTitle':persist();view='title';paused=false;modal=null;W.setMode('title');hazards.innerHTML='';roundLabels.clear();render();break;
 case 'map':modal='map';render();break;
 case 'collection':modal='collection';render();break;
 case 'facts':modal='facts';render();break;
 case 'share':share();break;
 case 'report':view='report';modal=null;W.setMode('report');render();break;
 case 'explore':view='explore';modal=null;W.setMode('town');W.player.group.position.set(0,.04,2);render();toast('설치된 기술과 자란 공방을 둘러보세요. 혁신 도감에 기록을 남길 수 있어요.');break;
 }}
ui.addEventListener('click',ev=>{if(ev.target.closest('[data-action="finishLine"]')){finishSpeech();return;}const el=ev.target.closest('button');if(!el||el.disabled)return;if(el.dataset.action)handle(el.dataset.action);else if(el.dataset.select!==undefined&&s.watched===3){s.selected=Number(el.dataset.select);W.react(W.presenters[s.selected],'thanks',2.2);W.burst(W.presenters[s.selected].group.position.x,3,-10.2,'#f6dd97',10);render();persist();beep();}else if(el.dataset.scale){s.scale=el.dataset.scale;render();persist();}else if(el.dataset.observation){if(!round||paused)return;const result=E.record(round,el.dataset.observation);if(result.ok){W.react(W.player,'thanks',2);beep('good');render();persist();}else{ui.querySelector('#record-hint').textContent=result.reason;beep('bad');}}else if(el.dataset.feedback){if(el.dataset.feedback!==s.result.weakness){ui.querySelector('#feedback-hint').textContent='사용 기록에 나온 문제와 조금 달라요. 위의 기록을 다시 보고 골라주세요.';beep('bad');return;}R.giveFeedback(s,el.dataset.feedback);navigate('growth');persist();toast('관찰한 문제를 정확히 전했어요. 공방에서 다음 발명을 만나봐요.');}else if(el.dataset.place){navigate(el.dataset.place);}});
labels.addEventListener('click',()=>handle('navigate'));
document.getElementById('world').addEventListener('pointerdown',ev=>{if(view==='title'||paused||modal)return;if(round)return;if(W.mode!=='town')return;const hit=W.hitAt(ev.clientX,ev.clientY),reaction=W.poke(hit);if(reaction?.actor!==undefined){const actor=W.actors[reaction.actor];if(actor===W.resident&&['need','feedback'].includes(s.phase)){navigate();return;}const p=actor.group.position;if(p.distanceTo(W.player.group.position)<4.5)arrive('greet:'+reaction.actor);else W.navigate(p.x+1.5,p.z+1.5,'greet:'+reaction.actor);return;}if(reaction?.text){W.react(W.dari,'cheer',1.4);toast(reaction.text);beep();return;}const p=W.pointFromScreen(ev.clientX,ev.clientY);if(p)W.navigate(p.x,p.z);});
document.getElementById('world').addEventListener('pointermove',ev=>{if(W.mode==='town'&&!paused&&!modal){const h=W.hitAt(ev.clientX,ev.clientY);W.hoverActor=h?.actor||null;document.getElementById('world').style.cursor=h?'pointer':'default';}});
window.addEventListener('keydown',ev=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(ev.code))ev.preventDefault();if(ev.repeat&&['KeyE','Escape'].includes(ev.code))return;if(ev.code==='Escape'){if(paused)handle('resume');else if(modal&&['map','collection','guide','demo','ai','evidence','facts','journal'].includes(modal))closeModal();else handle('pause');return;}if(ev.code==='Space'&&modal)finishSpeech();if(ev.code==='KeyE'&&!modal&&!paused&&W.mode==='town')handle('interact');if(!paused&&!modal)W.keys[ev.code]=true;});
window.addEventListener('keyup',ev=>{W.keys[ev.code]=false;});window.addEventListener('blur',()=>{W.keys={};W.stick={x:0,y:0};});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&view!=='title'&&!paused){paused=true;persist();render();}last=performance.now();});window.addEventListener('pagehide',persist);
function bindJoystick(){const joy=ui.querySelector('.joystick');if(!joy)return;const nub=joy.querySelector('span');const move=ev=>{const r=joy.getBoundingClientRect(),x=ev.clientX-r.left-r.width/2,y=ev.clientY-r.top-r.height/2,d=Math.max(25,Math.hypot(x,y));W.stick={x:x/d,y:y/d};nub.style.transform=`translate(${x/d*22}px,${y/d*22}px)`;};joy.addEventListener('pointerdown',ev=>{ev.preventDefault();joy.setPointerCapture(ev.pointerId);move(ev);});joy.addEventListener('pointermove',ev=>{if(joy.hasPointerCapture(ev.pointerId))move(ev);});const stop=()=>{W.stick={x:0,y:0};nub.style.transform='';};joy.addEventListener('pointerup',stop);joy.addEventListener('pointercancel',stop);}
function drawRound(){if(!round)return;const c=E.current(round),live=ui.querySelector('#pilot-live');if(live){const t=round.clock;live.textContent=t>=c.operatorAt?c.fake?(c.answer==='false'?'담당자: 위험이 아니었어요. 헛경보로 기록해 주세요.':'담당자: 일상 신호예요. 불필요한 대응 없이 확인했어요.'):(c.answer==='backup'?'제품이 놓쳐, 담당자가 추가 확인으로 대응했어요.':chapter().action+' 중이에요.'):c.notifyAt!==null&&t>=c.notifyAt?(s.product.old?'담당자가 장비를 직접 확인했어요.':'제품 알림이 기관에 도착했어요.'):c.fake?'위험이 아닌 일상 신호를 관찰하고 있어요.':'신호가 도착하는지 살펴보고 있어요.';}const bar=ui.querySelector('#pilot-progress');if(bar)bar.style.width=round.clock/c.duration*100+'%';}

function finishRound(){const result=E.summary(round);if(!R.finish(s,result))return;round=null;W.eventMeshes.forEach(g=>W.scene.remove(g));W.eventMeshes.clear();hazards.innerHTML='';roundLabels.clear();effects.clear();W.van.visible=false;W.drone.visible=false;modal='result';toastEl.textContent='';W.setMode('field');render();persist();beep(result.success?'good':'bad');}
function tick(now){const dt=Math.min(.08,Math.max(0,(now-last)/1000));last=now;if(toastEl.textContent&&now>toastUntil)toastEl.textContent='';if(!paused&&view!=='title'){
 if(s.phase==='pitch'&&!modal){s.pitchTime=Math.min(totalPitch,s.pitchTime+dt);s.watched=Math.min(3,Math.floor((s.pitchTime+.00001)/pitchDuration));const pi=pitchInfo(),n=pi.i*4+pi.step;if(s.pitchTime>=totalPitch){s.watched=3;s.phase='decision';render();persist();beep('good');}else if(n!==pitchPaint)render();const p=ui.querySelector('.live-progress span');if(p)p.style.width=s.pitchTime/totalPitch*100+'%';const replay=ui.querySelector('[data-action="repeatDemo"]');if(replay)replay.disabled=pi.local<8.2||pi.step===3;if(stageReply&&W.t>stageReply.until){stageReply=null;render();}}
 if(s.phase==='delivery'){s.deliveryTime=(s.deliveryTime||0)+dt;const f=Math.min(1,s.deliveryTime/7);if(f<.55){W.delivery.position.set(-22+f/.55*22,.3,1);W.delivery.rotation.y=Math.PI/2;}else{W.delivery.position.set(0,.3,1+(f-.55)/.45*21);W.delivery.rotation.y=0;}const bar=ui.querySelector('#delivery-progress');if(bar)bar.style.width=f*100+'%';if(f>=1){W.delivery.visible=false;W.install(s.product,s.season);s.phase='field';navigate('field');persist();toast('현장에 도착했어요. 담당 기관과 사용 기록을 모으러 가요.');}}
 if(round&&!modal){const before=round.phase;E.update(round,dt);W.updateRound(round);if(before!==round.phase){render();persist();}}
 if(seasonFlash>0){seasonFlash-=dt;if(seasonFlash<=0)render();}
 checkpoint+=dt;if(checkpoint>1){persist();checkpoint=0;}
 }
 const presenter=s.phase==='pitch'?pitchInfo().i:undefined;W.tick(paused?0:dt,{blocked:paused||!!modal||view==='title',presenter,phase:s.phase,modal,selected:s.selected,pitchTime:s.pitchTime,products:products(),season:s.season,history:s.history,prologueStep:s.prologueStep});if(!paused)tickSpeech(dt);if(round&&view!=='title')drawRound();
 const point=points[s.phase],marker=labels.querySelector('.world-hotspot');if(marker&&point){const p=W.project(point.x,5.4,point.z);marker.style.left=p.x+'px';marker.style.top=p.y+'px';marker.style.display=p.visible?'':'none';}const near=ui.querySelector('#nearby');if(near&&point){const close=Math.hypot(point.x-W.player.group.position.x,point.z-W.player.group.position.z)<3.1;near.innerHTML=close?`<button class="subtle" data-action="interact">E · ${point.name} 시작</button>`:W.path.length?'달이와 함께 걸어가는 중…':'길을 누르거나 방향키로 걸어요';}
 requestAnimationFrame(tick);
}
async function share(){try{const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const c=canvas.getContext('2d');c.fillStyle='#edf0d9';c.fillRect(0,0,1080,1350);c.fillStyle='#fffaea';c.beginPath();c.roundRect(45,45,990,1260,60);c.fill();const text=(t,x,y,size=32,color='#4f765d',align='left')=>{c.font=`900 ${size}px "Malgun Gothic",sans-serif`;c.fillStyle=color;c.textAlign=align;c.fillText(t,x,y);};text('첫 손님',90,160,68);text('나라가 처음 사주는 날',92,211,28,'#8a9877');text('나의 혁신 도감',90,315,43);text(`국민 안심 ${s.safety}  ·  혁신 성장 ${s.growth}`,90,375,31);text(`새 기술의 첫 사용 ${s.history.filter(h=>!h.product.old&&!h.product.fraud).length}번`,90,425,26,'#8c9a76');const entries=Object.values(s.companies).filter(x=>!x.name.includes('무엇이든'));const load=src=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=src;});if(!entries.length){text('아직 새로운 첫 손님 기록이 없어요.',90,650,30);text('다음 계절에는 어떤 발명을 만나볼까요?',90,710,26,'#899774');}for(let i=0;i<entries.length;i++){const item=entries[i],y=510+i*152;c.fillStyle='#e8ecd2';c.beginPath();c.roundRect(85,y,910,137,25);c.fill();const im=await load(A['animal'+item.sprite]);const k=112/Math.max(im.width,im.height);c.drawImage(im,105+(112-im.width*k)/2,y+12,im.width*k,im.height*k);text(item.name,245,y+53,31);text(['차고 · 첫 도전','공방 · 첫 주문','공장 · 다음 고객','해외 · 세계로'][item.level],245,y+99,25,'#8a9976');}const im=await load(A.narmi);c.drawImage(im,820,1130,115,145);text('처음은, 나라가 믿어줄게요.',90,1185,32);text('나르미·달이 © 조달청 · 가상 체험 게임',90,1240,18,'#9aa287');const a=document.createElement('a');a.download='첫손님_마을_혁신도감.png';a.href=canvas.toDataURL('image/png');document.body.appendChild(a);a.click();a.remove();toast('1080 × 1350 혁신 도감 이미지를 저장했어요.');}catch{toast('이미지 저장을 완료하지 못했어요. 다시 시도해 주세요.');}}

function npcChat(){const idx=npcFocus?W.actors.indexOf(npcFocus):0,key=npcFocus?.key?.startsWith('animal')?npcFocus.key:'dari';const prior=s.history.at(-1),line=prior?prior.success?'지난 계절에 설치한 기술 덕분에 마을이 든든해졌어요. 써본 사람들의 이야기도 꼭 전해주세요.':'지난번엔 조금 아쉬웠죠? 그래도 다시 고칠 기회를 준다면 더 좋아질 수 있어요.':['이 마을에는 아직 첫 손님을 만나지 못한 발명이 많아요.','발표회가 곧 시작된대요! 저는 맨 앞에서 응원할 거예요.','처음 써봤다는 기록, 발명가에게는 정말 큰 선물이에요.'][idx%3];return dialog(key==='dari'?'달이':'마을의 친구',key,'팀장님, 안녕하세요!',line,button('greetBack','같이 힘내요!','gold')+button('close','또 만나요','primary'));}
function startSpeech(){speechLines=[...ui.querySelectorAll('[data-speech]')].map(el=>{const full=el.dataset.speech;el.setAttribute('aria-label',full);el.textContent='';return {el,full,pos:0};});}
function finishSpeech(){speechLines.forEach(line=>{line.pos=line.full.length;line.el.textContent=line.full;});}
function tickSpeech(dt){for(const line of speechLines){if(line.pos>=line.full.length)continue;const before=Math.floor(line.pos/4);line.pos=Math.min(line.full.length,line.pos+dt*43);line.el.textContent=line.full.slice(0,Math.floor(line.pos));if(Math.floor(line.pos/4)!==before&&s.sound&&audioCtx&&audioCtx.state==='running'&&W.t-lastVoice>.08){lastVoice=W.t;const o=audioCtx.createOscillator(),g=audioCtx.createGain(),now=audioCtx.currentTime;o.type='sine';o.frequency.setValueAtTime(360+(line.full.charCodeAt(Math.floor(line.pos)-1)%6)*37,now);o.frequency.exponentialRampToValueAtTime(260,now+.055);g.gain.setValueAtTime(.012,now);g.gain.exponentialRampToValueAtTime(.001,now+.06);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(now+.07);}}}
ui.addEventListener('pointerdown',ev=>{const b=ev.target.closest('button');if(!b||b.disabled)return;const r=b.getBoundingClientRect(),dot=document.createElement('span');dot.className='click-ripple';dot.style.left=ev.clientX-r.left+'px';dot.style.top=ev.clientY-r.top+'px';b.appendChild(dot);setTimeout(()=>dot.remove(),550);});
ui.addEventListener('pointermove',ev=>{const b=ev.target.closest('.product');if(!b)return;const r=b.getBoundingClientRect();b.style.setProperty('--tilt-x',((.5-(ev.clientY-r.top)/r.height)*5)+'deg');b.style.setProperty('--tilt-y',(((ev.clientX-r.left)/r.width-.5)*5)+'deg');});


function prologueUI(){const p=S.prologue[s.prologueStep||0];return '<aside class="story-heading"><span class="tag">첫 출근 · '+((s.prologueStep||0)+1)+' / 3</span><h2>작은 부탁과, 첫 손님</h2></aside>'+dialog(p.who,p.key,p.title,p.text,button('prologueNext',p.button));}
function chapterLetterUI(){const prev=s.history.at(-1);return sheet(season().name+'의 새 편지가 도착했어요.',`<div class="resident-letter">${chapter().letter}</div><p>${prev?.success?'지난 계절에 쌓은 믿음이 다음 부탁으로 이어졌어요.':'지난 계절의 아쉬움도 다음 발명을 위한 기록이 되었어요.'}</p><div class="research-note"><b>이번 약속 · ${chapter().promise}</b><p>${chapter().need}</p></div>${promiseStrip()}<div class="actions">${button('readLetter','새 부탁을 들으러 함께 가기')}</div>`,{eyebrow:'모리와 도담 할머니 · 이어지는 사계절'});}
function journalUI(){return layer(`<h2>모리와 할머니의 약속 수첩</h2>${promiseStrip()}<div class="resident-letter">${chapter().letter}</div><ol class="journal-steps">${S.steps.map((name,i)=>`<li class="${i<=phaseIndex[s.phase]?'current':''}"><b>${name}</b><span>${['주민의 문제를 공공기관과 함께 정해요.','모든 발표를 듣고 실제 작동을 확인해요.','조달청이 먼저 구매해 사용기관에 제공해요.','운용은 공공기관이, 관찰과 기록은 나르미가 맡아요.','기록에 맞는 피드백으로 다음 발명을 바꿔요.'][i]}</span></li>`).join('')}</ol><div class="report-copy">이번 기준: <b>${chapter().criterion}</b><br>모을 보상: ${chapter().reward}</div><div class="actions">${button('close','부탁 계속하기')}</div>`);}

render();requestAnimationFrame(tick);
})();
